        };

        throw new Error('HTTP错误: ' + response.status);
    };

    return response;
};

// 只在未覆盖原生fetch时才进行覆盖
if (!window.originalFetch) {
    window.originalFetch = window.fetch;
    window.fetch = function() {
        return window.originalFetch.apply(this, arguments)
            .then(fetchErrorHandler)
