// 解除index页面锁定的脚本
function unlockIndexPage() {
    try {
        // 清除账号锁定状态
        localStorage.removeItem('accountLockedUntil');
        localStorage.removeItem('loginAttempts');

        // 清除系统锁定状态
        localStorage.removeItem('system-lock-state');

        // 清除所有与锁定相关的localStorage项
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key.startsWith('lock_') || key.includes('locked') || key.includes('Lock')) {
                localStorage.removeItem(key);
                i--; // 调整索引，因为删除了一个项
            }
        }

        /* 修复：注释掉调试日志 */ // console.log('成功解除index页面锁定！');
        alert('index页面锁定已解除，请刷新页面后重试。');

        // 刷新页面以应用更改
        location.reload();
    } catch (error) {
        console.error('解除锁定时发生错误:', error);
        alert('解除锁定失败，请检查控制台日志。');
    }
}

